// Notifications module
namespace App.Notifications
{
    public interface INotificationSender
    {
        Task SendAsync(Notification message);
    }

    internal class SmsSender : INotificationSender { }
    internal class EmailSender : INotificationSender { }
}

// Other modules can depend on INotificationSender only.
// They cannot reference SmsSender or EmailSender directly.

syntax = "proto3";
package notifications;

service NotificationService {
  rpc Send(SendRequest) returns (SendResponse);
}

message SendRequest {
  string userId = 1;
  string channel = 2;  // email, sms, push
  string template = 3;
  map<string, string> variables = 4;
}

message SendResponse {
  string messageId = 1;
  SendStatus status = 2;
}

enum SendStatus { QUEUED = 0; SENT = 1; FAILED = 2; }

// Inside the monolith, use a clean provider abstraction
public interface INotificationProvider
{
    Task SendAsync(NotificationMessage message);
}

public class SendGridEmailProvider : INotificationProvider { }
public class TwilioSmsProvider : INotificationProvider { }

// The rest of the app depends on INotificationProvider.
// Swapping providers requires zero boundary changes.
